{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Focused frameworks for daily wellbeing: outcomes, habits, and simple systems to move you forward.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <button class="nav-toggle" aria-expanded="false" aria-controls="site-nav">Menu</button>
      <nav id="site-nav" class="site-nav" aria-label="Primary">
        <ul>
          <li><a href="/">Home</a></li>
          <li><a href="about.html">Approach</a></li>
          <li><a href="services.html">Sessions</a></li>
          <li><a href="programs.html">Programs</a></li>
          <li><a href="pricing.html">Investment</a></li>
          <li><a href="testimonials.html">Stories</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Connect</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero split-diagonal reveal" id="hero">
      <div class="container hero-inner">
        <div class="hero-copy">
          <h1>Small shifts. Reliable results.</h1>
          <p class="sub">Practical frameworks that convert intention into repeatable habits — tailored to how your week actually flows.</p>
          <p class="muted">VIP Day offers available for focused, one-session system design.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button class="btn ghost" id="try-now">Try it now</button>
          </div>
          <p class="contact">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">email</a>.</p>
        </div>
        <div class="hero-visual">
          <div class="pattern-wrap">
            <img src="assets/img/pattern.svg" alt="decorative pattern" />
          </div>
          <div class="kv">
            <div class="kv-card">Outcomes-first planning</div>
            <div class="kv-card">Daily habit architecture</div>
            <div class="kv-card">Tools you can actually use</div>
          </div>
        </div>
      </div>
    </section>

    <section class="gallery reveal" id="gallery">
      <div class="container">
        <h2>Work samples</h2>
        <p class="lead">Snapshots from short intensives and week-long adjustments clients use to build steadier days.</p>
        <div class="cards">
          <article class="card">
            <div class="card-art"></div>
            <h3>Week Reset</h3>
            <p>Hands-on restructuring of your top three routines for better flow.</p>
          </article>
          <article class="card">
            <div class="card-art"></div>
            <h3>Focus Sprint</h3>
            <p>A concentrated session to lock down a realistic focus plan for the next month.</p>
          </article>
          <article class="card">
            <div class="card-art"></div>
            <h3>Relief Framework</h3>
            <p>Simple patterns to steady energy across unpredictable days.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="what-to-expect reveal" id="what">
      <div class="container">
        <h2>What to expect</h2>
        <p class="lead">No medical claims — only clear outcomes, repeatable habits, and frameworks that stick.</p>
        <ul>
          <li><strong>Outcome mapping:</strong> We start with what matters and reverse-engineer practice into your week.</li>
          <li><strong>Micro-habits:</strong> Tiny, high-leverage actions you can sustain.</li>
          <li><strong>Support tools:</strong> Checklists, simple trackers, and micro-routines to keep momentum.</li>
        </ul>
      </div>
    </section>

    <section class="objections reveal" id="objections">
      <div class="container">
        <h2>Questions people often have</h2>
        <div class="faq">
          <details>
            <summary>Will this take a lot of time?</summary>
            <p>Sessions focus on changes that fit your schedule — small daily moves that add up, not another long list of tasks.</p>
          </details>
          <details>
            <summary>Is this a clinical program?</summary>
            <p>No. These are behavioral frameworks and habit design practices intended to improve how routines support your goals.</p>
          </details>
          <details>
            <summary>Can I try a sample before booking?</summary>
            <p>Yes — use the "Try it now" guided exercise for a quick practical taste of the approach.</p>
          </details>
        </div>
      </div>
    </section>

    <section class="final-cta reveal" id="final-cta">
      <div class="container">
        <h2>Ready to build a day that works?</h2>
        <p>Book a focused session or choose a VIP Day to fast-track system design.</p>
        <a class="btn primary large" href="book.html">Reserve a session</a>
        <a class="btn ghost" href="contact.html">Talk first</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <div class="foot-brand">{{BUSINESS_NAME}} &middot; {{CITY}}, {{STATE}}</div>
      <div class="foot-links">
        <a href="privacy.html">Privacy</a>
        <a href="contact.html">Contact</a>
      </div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="guideModal" class="modal" aria-hidden="true">
    <div class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="guide-title">
      <button class="modal-close" aria-label="Close">×</button>
      <h3 id="guide-title">Try an exercise</h3>
      <div class="guide-tabs">
        <button class="tab active" data-mode="breath">Breathing</button>
        <button class="tab" data-mode="journaling">Journaling</button>
        <button class="tab" data-mode="intention">Intention</button>
      </div>
      <div class="guide-body">
        <section class="mode" data-mode="breath">
          <p class="guide-copy">Follow a slow 4-4 breath. Start the cycle and watch the circle expand on inhale.</p>
          <div class="breath-visual" aria-hidden="true">
            <svg viewBox="0 0 100 100" class="breath-svg"><circle cx="50" cy="50" r="30" class="breath-circle"/></svg>
          </div>
          <div class="controls">
            <label>Cycle length: <select id="breath-length"><option value="4">4s</option><option value="5">5s</option><option value="6">6s</option></select></label>
            <button class="btn" id="breath-start">Start</button>
            <button class="btn ghost" id="breath-stop">Stop</button>
          </div>
          <div class="breath-status" aria-live="polite"></div>
        </section>

        <section class="mode hidden" data-mode="journaling">
          <p class="guide-copy">Write for 5 minutes. Keep it private: a brief check-in to clarify what matters today.</p>
          <label>Timer: <select id="journal-length"><option value="3">3 min</option><option value="5" selected>5 min</option><option value="10">10 min</option></select></label>
          <textarea id="journal-text" placeholder="Start writing..." rows="6"></textarea>
          <div class="controls">
            <button class="btn" id="journal-start">Start timer</button>
            <button class="btn ghost" id="journal-save">Save</button>
            <span class="journal-timer" aria-live="polite"></span>
          </div>
        </section>

        <section class="mode hidden" data-mode="intention">
          <p class="guide-copy">Choose one clear intention for the next 24 hours and pin it to your routine.</p>
          <ul class="intent-list">
            <li><button class="intent">Prioritize one deep task</button></li>
            <li><button class="intent">Move for 15 minutes</button></li>
            <li><button class="intent">Limit meetings to essential</button></li>
            <li><button class="intent">Write a single progress note</button></li>
          </ul>
          <div class="intent-summary" aria-live="polite"></div>
          <div class="controls">
            <button class="btn" id="intent-set">Set intention</button>
          </div>
        </section>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
