{"path":"assets/css/styles.css","content":"/* Base layout and utilities */
:root{--bg:#fbfbfb;--muted:#6b6b6b;--accent:#2b6cb0;--accent-2:#0f4c81;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,'Noto Sans',sans-serif;color:#0f1724;background:var(--bg);}
.container{max-width:1100px;margin:0 auto;padding:2rem;}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:blur(4px);border-bottom:1px solid rgba(15,20,36,0.04);position:sticky;top:0;z-index:40}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:1rem}
.brand{font-weight:700;color:var(--accent-2);text-decoration:none;font-size:1.05rem}
.nav-toggle{display:none;padding:.5rem 1rem;border:0;background:transparent}
.site-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:1rem}
.site-nav a{color:inherit;text-decoration:none;padding:.3rem .5rem;border-radius:4px}
.site-nav a:hover{background:rgba(15,76,129,0.06)}

/* Split diagonal hero */
.split-diagonal{padding:0;margin:0;overflow:visible}
.hero-inner{display:grid;grid-template-columns:1fr 1fr;align-items:stretch;gap:2rem;min-height:60vh}
.hero-copy{display:flex;flex-direction:column;justify-content:center}
.hero-copy h1{font-size:2.2rem;margin:0 0 .6rem;color:#0b365b}
.hero-copy .sub{margin:0 0 1rem;color:var(--muted)}
.hero-copy .muted{color:var(--muted);font-size:.95rem;margin-bottom:1rem}
.hero-cta{display:flex;gap:.8rem;align-items:center}
.btn{display:inline-block;padding:.65rem 1rem;border-radius:8px;border:1px solid transparent;background:var(--card);cursor:pointer;text-decoration:none;color:inherit}
.btn.primary{background:linear-gradient(180deg,var(--accent),var(--accent-2));color:#fff}
.btn.ghost{background:transparent;border:1px solid rgba(15,20,36,0.06)}
.btn.large{padding:1rem 1.25rem}
.contact{margin-top:.8rem;color:var(--muted)}

.hero-visual{position:relative;display:flex;align-items:center;justify-content:center}
.pattern-wrap{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;overflow:hidden}
.pattern-wrap img{width:120%;height:120%;opacity:.12;transform:translateY(-4%)}
.kv{position:relative;display:flex;flex-direction:column;gap:.6rem;z-index:2}
.kv-card{background:var(--card);padding:.6rem .8rem;border-radius:10px;box-shadow:0 6px 20px rgba(12,34,56,0.06);font-weight:600}

/* Diagonal effect */
.hero-inner::before{content:'';position:absolute;right:0;top:0;bottom:0;width:50%;background:linear-gradient(180deg,transparent,rgba(255,255,255,0.02));clip-path:polygon(8% 0,100% 0,100% 100%,0% 100%);pointer-events:none}
.split-diagonal{position:relative}

/* Cards / gallery */
.gallery .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.card{background:var(--card);padding:1rem;border-radius:12px;box-shadow:0 6px 18px rgba(12,34,56,0.06)}
.card-art{height:120px;background:linear-gradient(135deg,rgba(43,108,176,0.12),rgba(15,76,129,0.08));border-radius:8px;margin-bottom:.8rem}

.what-to-expect ul{margin:1rem 0;padding-left:1.1rem}
.what-to-expect li{margin:0.6rem 0}

/* FAQ */
.faq details{background:var(--card);padding:1rem;border-radius:10px;margin-bottom:.6rem}
.faq summary{cursor:pointer;font-weight:600}

/* CTA */
.final-cta{text-align:center;padding:3rem 0;background:linear-gradient(180deg,rgba(15,76,129,0.03),transparent)}

/* Footer */
.site-footer{border-top:1px solid rgba(15,20,36,0.04);padding:1.5rem 0;margin-top:2rem}
.footer-inner{display:flex;justify-content:space-between;align-items:center}
.foot-links a{margin-left:1rem;color:var(--muted);text-decoration:none}

/* Modal */
.modal{position:fixed;inset:0;background:rgba(5,10,20,0.45);display:flex;align-items:center;justify-content:center;padding:2rem;opacity:0;pointer-events:none;transition:opacity .18s ease}
.modal[aria-hidden="false"]{opacity:1;pointer-events:auto}
.modal-panel{background:var(--card);width:min(720px,96vw);border-radius:12px;padding:1.2rem;box-shadow:0 20px 60px rgba(16,24,40,0.16);position:relative}
.modal-close{position:absolute;right:.6rem;top:.6rem;border:0;background:transparent;font-size:1.4rem}
.guide-tabs{display:flex;gap:.4rem;margin:.6rem 0 .8rem}
.guide-tabs .tab{padding:.45rem .6rem;border-radius:8px;background:rgba(15,76,129,0.04);border:1px solid rgba(15,76,129,0.04)}
.guide-tabs .tab.active{background:linear-gradient(180deg,rgba(43,108,176,0.12),rgba(15,76,129,0.08));font-weight:700}
.mode{padding:.6rem 0}
.mode.hidden{display:none}
.breath-visual{display:flex;align-items:center;justify-content:center;margin:1rem 0}
.breath-svg{width:160px;height:160px}
.breath-circle{fill:rgba(43,108,176,0.14);stroke:rgba(43,108,176,0.7);stroke-width:2;transform-origin:50% 50%;transition:transform .3s ease}
.controls{display:flex;gap:.6rem;align-items:center;margin-top:.6rem}
.journal-timer{margin-left:1rem;color:var(--muted)}
.intent-list{display:flex;flex-wrap:wrap;gap:.5rem;padding:0;margin:0;list-style:none}
.intent{background:rgba(15,76,129,0.06);border:0;padding:.5rem .7rem;border-radius:8px}
.intent-summary{margin-top:.6rem;font-weight:600}

/* Reveal animation */
.reveal{opacity:0;transform:translateY(18px);transition:opacity .5s ease,transform .5s cubic-bezier(.2,.9,.2,1)}
.reveal.visible{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none;opacity:1;transform:none}
  .breath-circle{transition:none}
}

/* Responsive */
@media (max-width:860px){
  .hero-inner{grid-template-columns:1fr;min-height:70vh}
  .pattern-wrap img{width:160%;height:160%}
  .site-nav{display:none}
  .nav-toggle{display:inline-block}
  .gallery .cards{grid-template-columns:1fr}
  .footer-inner{flex-direction:column;gap:.6rem}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  'use strict';
  // Utilities
  function qs(sel, ctx){ return (ctx||document).querySelector(sel); }
  function qsa(sel, ctx){ return Array.from((ctx||document).querySelectorAll(sel)); }

  // Mobile nav toggle
  var navToggle = qs('.nav-toggle');
  var siteNav = qs('#site-nav');
  if(navToggle){
    navToggle.addEventListener('click', function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!expanded));
      siteNav.style.display = expanded ? '' : 'block';
    });
  }

  // Scroll reveal with prefers-reduced-motion support
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var reveals = qsa('.reveal');
  if(prefersReduced){
    reveals.forEach(function(el){ el.classList.add('visible'); });
  } else if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); }});
    },{threshold:0.12});
    reveals.forEach(function(el){ io.observe(el); });
  } else {
    // fallback
    reveals.forEach(function(el){ el.classList.add('visible'); });
  }

  // Modal and guided exercise
  var modal = qs('#guideModal');
  var tryBtn = qs('#try-now');
  var closeBtn = qs('.modal-close');
  var tabs = qsa('.guide-tabs .tab');
  var modeSections = qsa('.mode');

  function openModal(){ modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
  function closeModal(){ modal.setAttribute('aria-hidden','true'); document.body.style.overflow=''; stopBreath(); stopJournalTimer(); }
  if(tryBtn) tryBtn.addEventListener('click', openModal);
  if(closeBtn) closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e){ if(e.target === modal) closeModal(); });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && modal.getAttribute('aria-hidden')==='false'){ closeModal(); }});

  // Tabs
  tabs.forEach(function(t){ t.addEventListener('click', function(){ tabs.forEach(function(x){x.classList.remove('active');}); t.classList.add('active'); var m = t.getAttribute('data-mode'); modeSections.forEach(function(s){ s.classList.toggle('hidden', s.getAttribute('data-mode') !== m); }); }); });

  // BREATHING
  var breathStart = qs('#breath-start');
  var breathStop = qs('#breath-stop');
  var breathLen = qs('#breath-length');
  var breathCircle = qs('.breath-circle');
  var breathStatus = qs('.breath-status');
  var breathTimer = null;
  var breathPhase = 0; // 0 inhale,1 hold,2 exhale,3 hold
  var breathRunning=false;

  function setBreathVisual(ratio){ // ratio 0..1
    var scale = 0.5 + ratio*1.1; // modest scale
    breathCircle.style.transform = 'scale(' + scale + ')';
  }

  function breathStep(){
    var seg = Number(breathLen.value) || 4;
    // simple 2-phase inhale/exhale equal length
    var period = seg*1000; // ms for inhale, ms for exhale
    var half = period/1000; // using length as inhale time
    // we'll animate using intervals for clarity
  }

  function startBreath(){
    if(breathRunning) return;
    breathRunning=true;
    var cycle = Number(breathLen.value) || 4; // seconds inhale / exhale
    var step = 50; // ms
    var t=0; var phase=0; // 0 inhale,1 exhale
    setBreathVisual(0);
    breathStatus.textContent = 'Starting...';
    breathTimer = setInterval(function(){
      t+=step;
      var ratio = (t % (cycle*1000)) / (cycle*1000); // 0..1 within phase
      if(Math.floor(t/(cycle*1000)) % 2 === 0){ // inhale phase
        setBreathVisual(ratio);
        breathStatus.textContent = 'Inhale';
      } else {
        setBreathVisual(1 - ratio);
        breathStatus.textContent = 'Exhale';
      }
    }, step);
  }
  function stopBreath(){ if(breathTimer){ clearInterval(breathTimer); breathTimer=null; breathRunning=false; setBreathVisual(0); breathStatus.textContent='Stopped'; }}
  if(breathStart) breathStart.addEventListener('click', startBreath);
  if(breathStop) breathStop.addEventListener('click', stopBreath);

  // JOURNALING
  var journalStart = qs('#journal-start');
  var journalSave = qs('#journal-save');
  var journalText = qs('#journal-text');
  var journalTimerLabel = qs('.journal-timer');
  var journalLen = qs('#journal-length');
  var journalInterval = null;
  var journalRemaining = 0;

  function startJournalTimer(){ if(journalInterval) return; journalRemaining = (Number(journalLen.value)||5)*60; journalTimerLabel.textContent = formatTime(journalRemaining);
    journalInterval = setInterval(function(){ journalRemaining--; journalTimerLabel.textContent = formatTime(journalRemaining); if(journalRemaining<=0){ clearInterval(journalInterval); journalInterval=null; journalTimerLabel.textContent='Done'; }} ,1000);
  }
  function stopJournalTimer(){ if(journalInterval){ clearInterval(journalInterval); journalInterval=null; journalTimerLabel.textContent=''; }}
  function formatTime(sec){ var m=Math.floor(sec/60), s=sec%60; return String(m)+':' + (s<10?'0':'')+String(s); }
  if(journalStart) journalStart.addEventListener('click', startJournalTimer);
  if(journalSave) journalSave.addEventListener('click', function(){ var text = journalText.value.trim(); if(text.length){ try{ localStorage.setItem('quick_journal_'+Date.now(), text); journalText.value=''; journalTimerLabel.textContent='Saved'; setTimeout(function(){ journalTimerLabel.textContent=''; },1400); }catch(e){ alert('Unable to save locally'); } } else { journalTimerLabel.textContent='No text to save'; setTimeout(function(){ journalTimerLabel.textContent=''; },1200);} });

  // INTENTION
  var intentButtons = qsa('.intent');
  var intentSummary = qs('.intent-summary');
  var intentSet = qs('#intent-set');
  var chosenIntent = '';
  intentButtons.forEach(function(b){ b.addEventListener('click', function(){ intentButtons.forEach(function(x){x.classList.remove('active');}); b.classList.add('active'); chosenIntent = b.textContent; intentSummary.textContent = 'Selected: ' + chosenIntent; }); });
  if(intentSet) intentSet.addEventListener('click', function(){ if(!chosenIntent){ intentSummary.textContent = 'Pick an intention first.'; return; } try{ navigator.clipboard && navigator.clipboard.writeText(chosenIntent); intentSummary.textContent = 'Pinned: ' + chosenIntent + ' (copied)'; }catch(e){ intentSummary.textContent = 'Pinned: ' + chosenIntent; } });

  // Accessibility: focus trap simple
  modal.addEventListener('keydown', function(e){ if(e.key === 'Tab'){ var focusable = modal.querySelectorAll('button, [href], input, textarea, select'); if(focusable.length){ var first = focusable[0], last = focusable[focusable.length-1]; if(e.shiftKey && document.activeElement === first){ e.preventDefault(); last.focus(); } else if(!e.shiftKey && document.activeElement === last){ e.preventDefault(); first.focus(); } } } });

  // Expose stop functions to window for safety
  window._wellnessGuide = { stopBreath: stopBreath, stopJournalTimer: stopJournalTimer };

})();"} 
